var MSSCustodyBulkNowUtils = Class.create();
MSSCustodyBulkNowUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    //Enablement of redesign

    enableTradeBasedLinking: function() {
        var enableTradeLink = gs.getProperty('x_hsb11_mss_c_proc.mssCustodyLinkTradesForBulk', false);
        return enableTradeLink;
    },

    //Enablement of redesign


    //bulk State Value // used in below function

    getBulkStateValue: function(stateVal) {
        try {

            var stateDisplayValue = "";
            switch (parseInt(stateVal)) {
                case 1:
                    stateDisplayValue = 'New';
                    break;
                case 2:
                    stateDisplayValue = 'Work in Progress';
                    break;
                case 3:
                    stateDisplayValue = 'Closed Complete';
                    break;
                case 4:
                    stateDisplayValue = 'Closed Rejected';
                    break;
                case 6:
                    stateDisplayValue = 'Awaiting Info';
                    break;
                case 7:
                    stateDisplayValue = 'Cancelled';
                    break;
                case 8:
                    stateDisplayValue = 'Reviewed';
                    break;

                default:
                    stateDisplayValue = 'Unknown State';
                    break;
            }

            return stateDisplayValue;
        } catch (ex) {
            gs.info('Error Received from MSSCustodyBulkNowUtils - getBulkStateValue ' + ex);
        }

    },

    //bulk State Value


    linkAssociatedBulk: function(tradesArray, bulkID, bulkNum, bulkStatus, tradeCount, outcomeSelected) {

        try {
            var totalCount = tradesArray ? tradesArray.toString().split(",").length : 0;
            var chunkSize = parseInt(gs.getProperty('x_hsb11_mss_c_proc.mssCustoyTradePerBulkSize'));
            if (totalCount > 0) {
                for (var i = 0; i < totalCount; i += chunkSize) {
                    var dynamicBatch = tradesArray ? tradesArray.toString().split(",").slice(i, i + chunkSize) : "";
                    var updateTradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                    updateTradeData.addEncodedQuery("sys_idIN" + dynamicBatch.toString());
                    updateTradeData.query();
                    updateTradeData.setValue('associated_bulk_id', bulkID);
                    updateTradeData.setValue('case_type', 'manual');
                    updateTradeData.setValue('bulk_process_stage', 'Maker');
                    //var existingData = updateTradeData.getValue('bulk_status_history');
                    //var tradeBulkData = {};
                    // try {
                    //     tradeBulkData = existingData ? JSON.parse(existingData) : {};
                    //     tradeBulkData[bulkNum] = {
                    //         "BulkStatus": bulkStatus ? bulkStatus.toString() : "",
                    //         "TradesCount": tradeCount ? tradeCount.toString() : "",
                    //         "Outcome": outcomeSelected ? outcomeSelected.toString() : ""

                    //     };
                    // } catch (ex) {
                    //     gs.info('Eror Parsing Data - linkAssociatedBulk ' + ex);
                    // }
                    // updateTradeData.bulk_status_history = tradeBulkData ? JSON.stringify(tradeBulkData, null, 2) : "";
                    updateTradeData.updateMultiple();
                }
            }
        } catch (ex) {
            gs.info('Eror from Script Include - linkAssociatedBulk ' + ex);
        }

    },



    //Linking Trades with Bulk

    linkTradeswithBulkSelected: function() {

        try {
            var getTradeList = this.getParameter('sysparm_selectedTrades'); //trades array //selected
            var bulkID = this.getParameter('sysparm_bulkID');
            var outcomeSelected = this.getParameter('sysparm_outcomeSelected');
            var tradeCount = this.getParameter('sysparm_tradeCount');
            var tradesArray = [];
            tradesArray = getTradeList;
            var getBulkID = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            getBulkID.get(bulkID);
            var bulkNum = getBulkID.number;
            var bulkStatus = getBulkID.state ? this.getBulkStateValue(getBulkID.state) : "";
            this.linkAssociatedBulk(tradesArray, bulkID, bulkNum, bulkStatus, tradeCount, outcomeSelected);

        } catch (ex) {
            gs.error('Error Received from MSSCustodyBulkNowUtils - linkTradeswithBulk ' + ex);
        }

    },


    //Linking Trades with Bulk


    linkTradeswithBulkFiltered: function() {
        try {
            var getFilteredList = this.getParameter('sysparm_filteredTrades'); //trades //filtered
            var bulkID = this.getParameter('sysparm_bulkID');
            var outcomeSelected = this.getParameter('sysparm_outcomeSelected');
            var tradeCount = this.getParameter('sysparm_tradeCount');
            var tradesArray = [];
            var grCustodyTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grCustodyTrade.addEncodedQuery(getFilteredList);
            grCustodyTrade.query();
            while (grCustodyTrade.next()) {
                tradesArray.push(grCustodyTrade.getValue('sys_id') + "");
            }
            var getBulkID = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            getBulkID.get(bulkID);
            var bulkNum = getBulkID.number;
            var bulkStatus = getBulkID.state ? this.getBulkStateValue(getBulkID.state) : "";
            this.linkAssociatedBulk(tradesArray, bulkID, bulkNum, bulkStatus, tradeCount, outcomeSelected);
        } catch (ex) {
            gs.error('Error Received from MSSCustodyBulkNowUtils - linkTradeswithBulkFiltered ' + ex);
        }

    },


    //update Trade Bulk Status History on Update of Bulk
    //Utilised in BR - Update Bulk Status History -State Change

    updateBulkStatusHistory(bulkID, bulkNumber, bulkState) {

        try {
            var getTradesToUpdate = [];
            var updateTrades = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
            updateTrades.addEncodedQuery("associated_bulk_id.sys_idSTARTSWITH" + bulkID);
            updateTrades.query();
            while (updateTrades.next()) {
                var bulkHistoryObj = updateTrades.bulk_status_history ? JSON.parse(updateTrades.bulk_status_history) : {};
                if (bulkHistoryObj && bulkHistoryObj[bulkNumber] && bulkHistoryObj[bulkNumber]["BulkStatus"]) {
                    bulkHistoryObj[bulkNumber]["BulkStatus"] = bulkState ? this.getBulkStateValue(bulkState) : "";
                }
                updateTrades.bulk_status_history = JSON.stringify(bulkHistoryObj, null, 2);
                updateTrades.update();
            }

        } catch (ex) {
            gs.error('Error from Script Include x_hsb11_mss_c_proc.MSSCustodyBulkNowUtils - updateBulkStatusHistory for bulk ID ' + bulkNumber + " " + ex);
        }
    },
    //update Trade Bulk Status History on Update of Bulk


    removeBulkFromTradesByNumber: function() {
        gs.info('redesign cancel bulk');
        var bulkSysId = this.getParameter('sysparm_bulkSysId');
        var bulkState = this.getParameter('sysparm_bulkState');
        var bulkNumber = this.getParameter('sysparm_bulkNumber');

        if (!bulkSysId)
            return;

        try {
            var getTrades = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            getTrades.addQuery('associated_bulk_id', bulkSysId);
            getTrades.query();
            while (getTrades.next()) {
                gs.info('redesign cancel trade');
                getTrades.setValue('associated_bulk_id', '');

                // update bulk_status_history
                // var bulkHistoryObj;
                // try {
                //     bulkHistoryObj = getTrades.getValue('bulk_status_history') ? JSON.parse(getTrades.getValue('bulk_status_history')) : {};
                // } catch (e) {
                //     bulkHistoryObj = {};
                // }

                // if (bulkHistoryObj && bulkHistoryObj[bulkNumber] && bulkHistoryObj[bulkNumber]['BulkStatus']) {
                //     bulkHistoryObj[bulkNumber]['BulkStatus'] = 'Maker Cancelled';
                // }

                // getTrades.setValue('bulk_status_history', JSON.stringify(bulkHistoryObj, null, 2));
                getTrades.setValue('bulk_process_stage', 'Maker Cancelled');
                getTrades.setValue('case_type', 'no_open_case');
                getTrades.update();
            }
            var getBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (getBulk.get(bulkSysId)) {
                getBulk.state = 7;
                getBulk.update();
                gs.info('redesign bulk cancelled');
            }
        } catch (ex) {
            gs.info('Error from Script Include x_hsb11_mss_c_proc.MSSCustodyBulkNowUtils - removeBulkFromTradesByNumber for bulk ID  ' + ex);

        }
    },

    removeTrades: function() {
        gs.info('removeTrades start');
        var tradeIds = this.getParameter('sysparm_tradeIDs') || '';
        var bulkSysId = this.getParameter('sysparm_bulkSysId');
        var bulkNumber = this.getParameter('sysparm_bulkNumber');

        try {
            var ids = tradeIds.split(',');
            var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');

            for (var i = 0; i < ids.length; i++) {
                var id = ids[i].trim();
                if (!trade.get(id))
                    continue;

                // remove association
                trade.setValue('associated_bulk_id', '');

                // update bulk_status_history exactly like your example
                // var bulkHistoryObj;
                // try {
                //     bulkHistoryObj = trade.getValue('bulk_status_history') ? JSON.parse(trade.getValue('bulk_status_history')) : {};
                // } catch (e) {
                //     bulkHistoryObj = {};
                // }

                // if (bulkHistoryObj && bulkHistoryObj[bulkNumber] && bulkHistoryObj[bulkNumber]['BulkStatus']) {
                //     bulkHistoryObj[bulkNumber]['BulkStatus'] = 'Maker Rejected';
                // }

                // trade.setValue('bulk_status_history', JSON.stringify(bulkHistoryObj, null, 2));
                trade.setValue('bulk_process_stage', 'Maker Cancelled');
                trade.setValue('case_type', 'no_open_case');
                trade.update();
            }
            var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
            ga.addQuery('associated_bulk_id', bulkSysId);
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) {
                var count = parseInt(ga.getAggregate('COUNT'), 10) || 0;
                var gBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
                if (gBulk.get(bulkSysId)) {
                    gBulk.setValue('active_trade_count', count);
                    if (count === 0) {
                        gBulk.setValue('state', 7);
                    }
                    gBulk.update();
                }
            }
        } catch (ex) {
            gs.info('Error from Script Include x_hsb11_mss_c_proc.MSSCustodyBulkNowUtils - removeTrades for bulk ID  ' + ex);
        }
    },

    getBulkType: function(bulkId) {

        try {

            gs.info("getBulkType received Bulk ID " + bulkId)

            var getBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (getBulk.get(bulkId)) {

                if (gs.getUserID() == getBulk.assigned_to.sys_id) {
                    gs.info("getBulkType received Bulk ID " + getBulk.bulk_task_type.toString());
                    return getBulk.bulk_task_type.toString();
                } else {
                    return 'Not Elibigle';
                }


            }
        } catch (ex) {
            gs.info('Erro Received from getBulkType ' + ex);
        }
    },

    rejectAllChecker: function() {
        gs.info('rejectAllChecker start');
        var bulkSysId = this.getParameter('sysparm_bulkSysId');
        var bulkNumber = this.getParameter('sysparm_bulkNumber');

        if (!bulkSysId)
            return;

        try {
            var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            trade.addQuery('associated_bulk_id', bulkSysId);
            trade.query();
            while (trade.next()) {
                gs.info('rejectAllChecker processing trade: ' + trade.getUniqueValue());
                // trade.setValue('associated_bulk_id', '');

                // var bulkHistoryObj;
                // try {
                //     bulkHistoryObj = trade.getValue('bulk_status_history') ? JSON.parse(trade.getValue('bulk_status_history')) : {};
                // } catch (e) {
                //     bulkHistoryObj = {};
                // }

                // if (bulkHistoryObj && bulkHistoryObj[bulkNumber] && bulkHistoryObj[bulkNumber]['BulkStatus']) {
                //     bulkHistoryObj[bulkNumber]['BulkStatus'] = 'Checker Rejected';
                // }

                // trade.setValue('bulk_status_history', JSON.stringify(bulkHistoryObj, null, 2));
                // trade.setValue('case_type', 'no_open_case');
                trade.setValue('bulk_process_stage', 'Checker - To Be Rejected');
                trade.update();
            }

            var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
            ga.addQuery('associated_bulk_id', bulkSysId);
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) {
                var count = parseInt(ga.getAggregate('COUNT'), 10) || 0;
                var gBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
                if (gBulk.get(bulkSysId)) {
                    gBulk.setValue('active_trade_count', count);
                    if (count === 0) {
                        gBulk.setValue('state', 7);
                    }
                    gBulk.update();
                }
            }
            gs.info('rejectAllChecker completed for bulk: ' + bulkSysId);
        } catch (ex) {
            gs.info('Error from Script Include x_hsb11_mss_c_proc.MSSCustodyBulkNowUtils - rejectAllChecker: ' + ex);
        }
    },

    removeSelectedChecker: function() {
        gs.info('removeSelectedChecker start');
        var tradeIds = this.getParameter('sysparm_tradeIDs');
        var bulkSysId = this.getParameter('sysparm_bulkSysId');
        var bulkNumber = this.getParameter('sysparm_bulkNumber');

        if (!tradeIds)
            return 'ERROR|No trade ids supplied';

        try {
            var ids = tradeIds.split(',');
            var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');

            for (var i = 0; i < ids.length; i++) {
                var id = ids[i].trim();
                if (!trade.get(id))
                    continue;

                // remove association
                // trade.setValue('associated_bulk_id', '');

                // // update bulk_status_history
                // var bulkHistoryObj;
                // try {
                //     bulkHistoryObj = trade.getValue('bulk_status_history') ? JSON.parse(trade.getValue('bulk_status_history')) : {};
                // } catch (e) {
                //     bulkHistoryObj = {};
                // }

                // if (bulkHistoryObj && bulkHistoryObj[bulkNumber] && bulkHistoryObj[bulkNumber]['BulkStatus']) {
                //     bulkHistoryObj[bulkNumber]['BulkStatus'] = 'Checker Rejected';
                // }

                // trade.setValue('bulk_status_history', JSON.stringify(bulkHistoryObj, null, 2));
                trade.setValue('bulk_process_stage', 'Checker - To Be Rejected');
                // trade.setValue('case_type', 'no_open_case');
                trade.update();
            }

            var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
            ga.addQuery('associated_bulk_id', bulkSysId);
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) {
                var count = parseInt(ga.getAggregate('COUNT'), 10) || 0;
                var gBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
                if (gBulk.get(bulkSysId)) {
                    gBulk.setValue('active_trade_count', count);
                    if (count === 0) {
                        gBulk.setValue('state', 7);
                    }
                    gBulk.update();
                }
            }

            gs.info('removeSelectedChecker completed for bulk: ' + bulkSysId);
        } catch (ex) {
            gs.info('Error from Script Include x_hsb11_mss_c_proc.MSSCustodyBulkNowUtils - rejectSelectedChecker: ' + ex);
        }
    },

    updateBulkIDtoTrades: function(tradesArr) {

        gs.info('trade ID ' + sampleArr.length);
        var totalCount = tradesArr.length;
        var chunkSize = 100;

        for (var i = 0; i < totalCount; i += chunkSize) {

            var dynamicBatch = tradesArr.slice(i, i + chunkSize);

            // gs.info('dynamicBatch ' + typeof(dynamicBatch) + dynamicBatch.length + " " + dynamicBatch);
            var grInc = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grInc.addEncodedQuery("sys_idIN" + dynamicBatch.toString());
            grInc.query();
            grInc.setValue('stop_price', 8);
            grInc.updateMultiple();

        }
    },


    getCountOfTrades: function() { //MSSCUSTODY- 3544
        try {
            var bulkid = this.getParameter('sysparm_bulkid');
            var getTrades = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
            getTrades.addEncodedQuery('associated_bulk_id.sys_idSTARTSWITH' + bulkid);
            getTrades.addAggregate('COUNT');
            getTrades.query();
            if (getTrades.next()) {
                return getTrades.getAggregate('COUNT');
            }
        } catch (e) {
            gs.info('Error while getting getCountOfTrades MSSCustodyBulkNowUtils - getCountOfTrades ' + e.message);

        }
    },

    getBandSummary: function() {
        try {
            var bulkId = this.getParameter('sysparm_bulkid');
            var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade'); // Replace with your task table name
            tradeGR.addEncodedQuery('associated_bulk_id.sys_idSTARTSWITH' + bulkId);
            tradeGR.query();
            var bandCounts = {};
            var total = 0;
            while (tradeGR.next()) {
                var band = tradeGR.eligible_band + ''; // Dot-walk to trade's eligible_band
                bandCounts[band] = (bandCounts[band] || 0) + 1;
                total++;
            }
            return JSON.stringify({
                total: total,
                bandCounts: bandCounts
            });
        } catch (e) {
            gs.info('Error while getting band summary MSSCustodyBulkNowUtils - getBandSummary ' + e.message);

        }
    },

    updateBulkonMakerSubmit: function() {
        try {
            var bulkid = this.getParameter('sysparm_bulkid');
            var assignmentgroup = this.getParameter('sysparm_assignmentgroup');
            var assignedto = this.getParameter('sysparm_assignedto');
            var outcome = this.getParameter('sysparm_outcome');
            var advice = this.getParameter('sysparm_advice');
            var reasoncode = this.getParameter('sysparm_reasoncode');
            var reasondesc = this.getParameter('sysparm_reasondescription');
            var suspend = this.getParameter('sysparm_suspend');
            var cancelby = this.getParameter('sysparm_cancelby');
            var setttype = this.getParameter('sysparm_settlementtype');
            var bktobkinfo = this.getParameter('sysparm_bktobk');
            var cancreference = this.getParameter('sysparm_cancellationreference');
            var cancelcharge = this.getParameter('sysparm_collectcancelcharge');
            //adding as part of 4901
            var settDate = this.getParameter('sysparm_settDate');
            var fxrTD = this.getParameter('sysparm_fxrTD');
            var valDate = this.getParameter('sysparm_valDate');
            var comments = this.getParameter('sysparm_comments'); // MSSCUSTODY-6379
            var uploadType = this.getParameter('sysparm_uploadType'); // MSSCUSTODY-6821 // 7191
            var tasksCount = this.getParameter('sysparm_tasksCount');

            //MSSCUSTODY-6087
            var fxcx = this.getParameter('sysparm_fxcx'); //MSSCUSTODY-6087
            var gdi = this.getParameter('sysparm_gdi');

            //MSSCUSTODY-7266
            var subOutcome = this.getParameter('sysparm_subOutcome');
            var transRef = this.getParameter('sysparm_transRef');
            var transType = this.getParameter('sysparm_transType');
            var legStatus = this.getParameter('sysparm_legStatus');
            var switchRef = this.getParameter('sysparm_switchRef');
            var counterpartyCode = this.getParameter('sysparm_counterpartyCode');
            var trdSettDate = this.getParameter('sysparm_trdSettDate');
            var trdLegStat = this.getParameter('sysparm_trdLegStat');
            var trdLocCode = this.getParameter('sysparm_trdLocCode');
            var trdQuantity = this.getParameter('sysparm_trdQuantity');
            var trdScripHold = this.getParameter('sysparm_trdScripHold');
            var trdSecAccnt = this.getParameter('sysparm_trdSecAccnt');
            var trdSettAmt = this.getParameter('sysparm_trdSettAmt');
            var trdSwitchAccnt = this.getParameter('sysparm_trdSwitchAccnt');
            var trdTransRef = this.getParameter('sysparm_trdTransRef');
            var trdTransType = this.getParameter('sysparm_trdTransType');

            //MSSCUSTODY-7057
            var transRefLink = this.getParameter('sysparm_transRefLink');
            var gdiInd = this.getParameter('sysparm_gdiInd');
            var holdInd = this.getParameter('sysparm_holdInd');
            var settleInd = this.getParameter('sysparm_settleInd');

            //
            var linkRef = this.getParameter('sysparm_linRef');
            var tranRef = this.getParameter('sysparm_dTranRef');
            var dHold = this.getParameter('sysparm_dHold');
            var dSettQntty = this.getParameter('sysparm_dSetllment');
            var dLegacy = this.getParameter('sysparm_dLegacyStatus');
            var dTxnType = this.getParameter('sysparm_dTxnType');

            //update bulk record after all tasks are processed 

            var grCustodyTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grCustodyTrade.addEncodedQuery('associated_bulk_id=' + bulkid);
            grCustodyTrade.query();
            while (grCustodyTrade.next()) {
                grCustodyTrade.setValue('bulk_process_stage', 'Checker - To Be Approved');
                grCustodyTrade.update();
            }

            var grbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
            grbulk.addQuery("sys_id", bulkid);
            grbulk.query();
            if (grbulk.next()) {
                if (grbulk.outcome == 'Review and closed the task') {
                    grbulk.bulk_task_type = 'GHSS Handler';
                } else {
                    grbulk.bulk_task_type = 'Checker';
                }
                grbulk.current_maker_assignee = assignedto;
                grbulk.maker_assignment_group = assignmentgroup;
                grbulk.new_maker_task_assignee = assignedto;
                grbulk.outcome = outcome;
                grbulk.advice = advice;
                grbulk.reason_code = reasoncode;
                grbulk.reason_description = reasondesc;
                grbulk.suspend = suspend;
                grbulk.cancel_by = cancelby;
                grbulk.settlement_type = setttype;
                grbulk.bk_to_bk_info = bktobkinfo;
                grbulk.cancellation_reference = cancreference;
                grbulk.collect_cancel_charge = cancelcharge;
                grbulk.assigned_to = '';
                grbulk.lock = false; //MSSCUSTODY-3993
                //adding as part of 4901
                grbulk.settlement_date = settDate;
                grbulk.fxr_td = fxrTD;
                grbulk.value_date = valDate;
                grbulk.comments = comments; // MSSCUSTODY-6379

                //MSSCUSTODY-6087
                grbulk.fx_cx = fxcx;
                grbulk.gdi = gdi;

                //MSSCUSTODY-7266
                grbulk.sub_outcome = subOutcome;
                grbulk.transaction_reference = transRef;
                grbulk.transaction_type_display = transType;
                grbulk.legacy_status_display = legStatus;
                grbulk.pair_switch_reference = switchRef;
                grbulk.switch_counterparty_code = counterpartyCode;
                grbulk.trade_settlement_date = trdSettDate;
                grbulk.trade_legacy_status = trdLegStat;
                grbulk.trade_location_code = trdLocCode;
                grbulk.trade_quantity = trdQuantity;
                grbulk.trade_scrip_hold_indicator = trdScripHold;
                grbulk.trade_securities_account = trdSecAccnt;
                grbulk.trade_settlement_amount = trdSettAmt;
                grbulk.trade_switch_account = trdSwitchAccnt;
                grbulk.trade_transaction_reference = trdTransRef;
                grbulk.trade_transaction_type = trdTransType;

                //MSSCUSTODY-7057
                grbulk.transaction_reference_link = transRefLink;
                grbulk.amend_gdi_indicator = gdiInd;
                grbulk.amend_cash_hold_indicator = holdInd;
                grbulk.settle_link = settleInd;

                //MSSCUSTODY-8162
                grbulk.trade_link_reference = linkRef;
                grbulk.d_transaction_reference = tranRef;
                grbulk.d_transaction_type = dTxnType;
                grbulk.d_settlement_quantity = dSettQntty;
                grbulk.d_legacy_status = dLegacy;
                grbulk.d_hold_indicator = dHold;


                grbulk.update();
            }

            return true;
        } catch (e) {
            gs.info('Error while updating Bulk record on submission MSSCustodyBulkNowUtils - updateBulkonMakerSubmit ' + e.message);

        }

    },

    updateBulkonCheckerSubmit: function() {
        try {

            var bulkid = this.getParameter('sysparm_bulkid');
            var assignmentgroup = this.getParameter('sysparm_assignmentgroup');
            var assignedto = this.getParameter('sysparm_assignedto');
            var decision_reason = this.getParameter('sysparm_decision_reason');
            var makerAssignmentgroup = this.getParameter('sysparm_makerAssignmentgroup');
            var reasondescription = this.getParameter('sysparm_reasondescription');
            var newMakerasignee = this.getParameter('sysparm_newMakerasignee');
            var comments = this.getParameter('sysparm_comments');
            var rejecttaskflag = this.getParameter('sysparm_rejecttaskflag');
            var decision = this.getParameter('sysparm_decision');
            var outcome = this.getParameter('sysparm_outcome');

            var getbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
            if (getbulk.get(bulkid)) {
                getbulk.redesigned_bulk = true;
				getbulk.u_current_checker_assignee = assignedto;
                getbulk.update();
            }

            var grCustodyTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grCustodyTrade.addEncodedQuery('associated_bulk_id=' + bulkid);
            grCustodyTrade.query();
            while (grCustodyTrade.next()) {
                if (grCustodyTrade.bulk_process_stage.toString() == 'Checker - To Be Rejected') {
                    grCustodyTrade.setValue('associated_bulk_id', '');
                    grCustodyTrade.setValue('bulk_process_stage', '');
                    grCustodyTrade.setValue('case_type', 'no_open_case');
                    grCustodyTrade.update();
                } else if (grCustodyTrade.bulk_process_stage.toString() == 'Checker - To Be Approved') {
                    grCustodyTrade.setValue('bulk_process_stage', 'GHSS Handler');
                    grCustodyTrade.update();
                }
            }

            var cases = this.linkBulkWithCaseTaskHandler(outcome, bulkid);

            var grbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
            grbulk.addQuery("sys_id", bulkid);
            grbulk.query();
            if (grbulk.next()) {

                grbulk.bulk_task_type = 'GHSS Handler';
                grbulk.decision_reason = decision_reason;
                grbulk.maker_assignment_group = makerAssignmentgroup;
                grbulk.new_maker_task_assignee = newMakerasignee;
                grbulk.comments = comments;
                grbulk.update();

            }
            return true;

        } catch (e) {
            gs.info('Error while updating Bulk record on submission MSSCustodyBulkNowUtils - updateBulkonCheckerSubmit ' + e.message);

        }

    },

