    updateCheckerTaskTypeRedesign: function() {
        try {
            var bulkid = this.getParameter('sysparm_bulkSysID');
            var grCustodyTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grCustodyTrade.addEncodedQuery('associated_bulk_id=' + bulkid + '^bulk_process_stage=Checker - To Be Rejected');
            grCustodyTrade.query();
            while (grCustodyTrade.next()) {
                grCustodyTrade.setValue('bulk_process_stage', 'Checker - To Be Approved');
                grCustodyTrade.update();
            }
        } catch (e) {
            gs.info('Error in checker cancel: ' + e.message);
        }

    },

    type: 'MSSCustodyBulkNowUtils'
});
